/**  コピー・移動・削除の依頼. */
export type TransferRequest_Deserialize = {
	/**  操作の種類. */
	kind: TransferKind,
	/**  対象のパス. */
	sources: string[],
	/**  コピー・移動先のディレクトリ. 削除では使わない. */
	dest_dir?: string | null,
	/**  true の場合, 同名のファイルを上書きする. */
	overwrite?: boolean,
	/**  true の場合, 削除でゴミ箱を使わず完全に削除する. */
	permanent?: boolean,
	/**  コピー時に指定した名前でコピーする (Copy のみ. 単一ファイルに限定). */
	dest_name?: string | null,
	/**
	 *  コピー・移動しない対象の中のファイルのパス (同名のディレクトリを統合するとき, 上書きしないと
	 *  答えたもの). 移動では, 移動元に残る.
	 */
	skip?: string[],
};

/**  コピー・移動・削除の依頼. */
export type TransferRequest_Serialize = {
	/**  操作の種類. */
	kind: TransferKind,
	/**  対象のパス. */
	sources: string[],
	/**  コピー・移動先のディレクトリ. 削除では使わない. */
	dest_dir: string | null,
	/**  true の場合, 同名のファイルを上書きする. */
	overwrite: boolean,
	/**  true の場合, 削除でゴミ箱を使わず完全に削除する. */
	permanent: boolean,
	/**  コピー時に指定した名前でコピーする (Copy のみ. 単一ファイルに限定). */
	dest_name: string | null,
	/**
	 *  コピー・移動しない対象の中のファイルのパス (同名のディレクトリを統合するとき, 上書きしないと
	 *  答えたもの). 移動では, 移動元に残る.
	 */
	skip: string[],
};

